        draft.addEventListener(MARKDOWN_FLUSH_REQUESTED_EVENT, handleFlushRequest)

        return () => draft.removeEventListener(MARKDOWN_FLUSH_REQUESTED_EVENT, handleFlushRequest)
    }, [draft, flush])
}

