    const preventViewportOverflowModifier = {
        name: 'preventOverflow',
        options: {
            altAxis: true,
            boundary: boundaryElement ?? 'clippingParents',
            padding: { bottom: bottomInset, left: VIEWPORT_MARGIN, right: VIEWPORT_MARGIN, top: VIEWPORT_MARGIN },
            tether: false,
